(function(){'use strict';if(!window.htmx)return;window.toggleFacetDropdown=function(btn,event){if(event)event.stopPropagation();var wrap=btn.closest('.facet-dropdown-wrap');if(!wrap)return;var menu=wrap.querySelector('.facet-dropdown-menu');if(!menu)return;var isOpen=menu.classList.contains('open');window.closeFacetDropdown();if(!isOpen){menu.classList.add('open');btn.setAttribute('aria-expanded','true');}};window.closeFacetDropdown=function(event){if(event&&event.stopPropagation)event.stopPropagation();document.querySelectorAll('.facet-dropdown-menu.open').forEach(function(menu){if(menu.__closing)return;menu.__closing=true;menu.classList.add('closing');var wrap=menu.closest('.facet-dropdown-wrap');var btn=wrap?wrap.querySelector('.facet-btn'):null;if(btn)btn.setAttribute('aria-expanded','false');setTimeout(function(){menu.classList.remove('open','closing');menu.__closing=false;},150);});};document.addEventListener('click',function(e){if(!e.target.closest('.facet-dropdown-wrap')){window.closeFacetDropdown();}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){window.closeFacetDropdown();}});function applyImgQuality(root){if(!window.pickImgSrc)return;(root||document).querySelectorAll('img[data-img-small]').forEach(function(img){var s=window.pickImgSrc(img.getAttribute('data-img'),img.getAttribute('data-img-small'));if(s&&img.getAttribute('src')!==s)img.src=s;});}
function updateSubcategoryScrollControls(row){if(!row)return;var track=row.querySelector('.ctrl-sub-bar-wrap');var bar=track&&track.querySelector('.ctrl-sub-bar');var left=row.querySelector('.subcategory-scroll-btn--left');var right=row.querySelector('.subcategory-scroll-btn--right');if(!track||!bar||!left||!right)return;var overflow=track.scrollWidth>track.clientWidth+4;if(!overflow){left.setAttribute('hidden','');right.setAttribute('hidden','');left.style.display='none';right.style.display='none';return;}
left.removeAttribute('hidden');right.removeAttribute('hidden');left.style.display='';right.style.display='';var maxScroll=track.scrollWidth-track.clientWidth;var pos=track.scrollLeft;var rtl=getComputedStyle(track).direction==='rtl';var hiddenLeft,hiddenRight;if(rtl){var fromStart=Math.abs(pos);if(pos>0){hiddenLeft=fromStart;hiddenRight=maxScroll-fromStart;}else{hiddenLeft=maxScroll-fromStart;hiddenRight=fromStart;}}else{hiddenLeft=Math.max(0,pos);hiddenRight=Math.max(0,maxScroll-pos);}
left.disabled=hiddenLeft<4;right.disabled=hiddenRight<4;}
function bindSubcategoryScrollers(root){var scope=root||document;scope.querySelectorAll('.catalog-subcategory-row').forEach(function(row){var track=row.querySelector('.ctrl-sub-bar-wrap');if(!track)return;if(track.getAttribute('data-scroll-controls-bound')!=='1'){track.setAttribute('data-scroll-controls-bound','1');track.addEventListener('scroll',function(){requestAnimationFrame(function(){updateSubcategoryScrollControls(row);});},{passive:true});}
requestAnimationFrame(function(){updateSubcategoryScrollControls(row);});});}
function revealActiveSubcategory(root){var scope=root||document;requestAnimationFrame(function(){scope.querySelectorAll('.ctrl-sub-bar-wrap').forEach(function(track){var active=track.querySelector('.sub-pill.active');if(!active)return;var firstPill=track.querySelector('.sub-pill:first-child');if(active===firstPill){try{track.scrollTo({left:0,behavior:'instant'});}catch(e){track.scrollLeft=0;}
requestAnimationFrame(function(){updateSubcategoryScrollControls(track.closest('.catalog-subcategory-row'));});return;}
var pageX=window.scrollX;var pageY=window.scrollY;active.scrollIntoView({behavior:'auto',block:'nearest',inline:'nearest'});if(window.scrollX!==pageX||window.scrollY!==pageY){window.scrollTo({left:pageX,top:pageY,behavior:'auto'});}
requestAnimationFrame(function(){updateSubcategoryScrollControls(track.closest('.catalog-subcategory-row'));});});});}
document.addEventListener('click',function(event){var button=event.target.closest('.subcategory-scroll-btn');if(!button||button.disabled)return;var row=button.closest('.catalog-subcategory-row');var track=row&&row.querySelector('.ctrl-sub-bar-wrap');if(!track)return;var distance=Math.max(120,Math.round(track.clientWidth*.62));var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;track.scrollBy({left:button.getAttribute('data-subcategory-scroll')==='left'?-distance:distance,behavior:reduced?'auto':'smooth',});});window.addEventListener('resize',function(){document.querySelectorAll('.catalog-subcategory-row').forEach(updateSubcategoryScrollControls);},{passive:true});if(document.fonts&&document.fonts.ready&&document.fonts.status!=='loaded'){document.fonts.ready.then(function(){document.querySelectorAll('.catalog-subcategory-row').forEach(updateSubcategoryScrollControls);});}
var scrollRequestId=0;window.cancelCatalogAutoScroll=function(){scrollRequestId+=1;};function catalogVisibleTopOffset(){var header=document.querySelector('.glass-header');if(!header)return 0;var style=window.getComputedStyle(header);if(style.position!=='sticky'&&style.position!=='fixed')return 0;var rect=header.getBoundingClientRect();if(rect.bottom<=0||rect.top>1)return 0;return Math.ceil(rect.bottom)+8;}
window.catalogVisibleTopOffset=catalogVisibleTopOffset;function scrollCatalogTarget(el,offset,behavior){var requestId=++scrollRequestId;requestAnimationFrame(function(){requestAnimationFrame(function(){if(requestId!==scrollRequestId||!el.isConnected)return;var y=el.getBoundingClientRect().top+window.scrollY-offset;window.scrollTo({top:Math.max(0,y),behavior:behavior});});});}
document.body.addEventListener('htmx:afterSwap',function(e){var target=e.detail&&e.detail.target;if(!target)return;var root=target.classList.contains('hx-frag')?target:target.querySelector('.hx-frag');if(!root)return;if(window.removeCatalogScrollSpacer)window.removeCatalogScrollSpacer();var wrap=root.getAttribute('data-wrap')?document.querySelector(root.getAttribute('data-wrap')):null;var hint=root.getAttribute('data-hint')?document.querySelector(root.getAttribute('data-hint')):null;if(root.getAttribute('data-visible')==='1'){if(wrap){if(window.cancelCatalogClose)window.cancelCatalogClose();wrap.style.display='';wrap.classList.remove('results-opening');void wrap.offsetWidth;wrap.classList.add('results-opening');}
if(hint)hint.style.display='none';}else{if(wrap)wrap.style.display='none';if(hint)hint.style.display='';}
if(window.updateAddButtons)window.updateAddButtons();applyImgQuality(root);bindSubcategoryScrollers(root);revealActiveSubcategory(root);if(root.getAttribute('data-history')!=='push'){var url=root.getAttribute('data-url');if(url){try{history.replaceState(null,'',url);}catch(err){}}}
var st=root.getAttribute('data-scrollto');if(st){var el=st==='grid'?(root.querySelector('#gamesGrid, #moviesGrid, #productsGrid, #programsGrid')||root):(root.querySelector('.catalog-results-toolbar')||root);var offset=catalogVisibleTopOffset();if(st==='grid')offset+=12;var behavior=(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)?'auto':'smooth';scrollCatalogTarget(el,offset,behavior);}});if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){applyImgQuality(document);bindSubcategoryScrollers(document);revealActiveSubcategory(document);});}else{applyImgQuality(document);bindSubcategoryScrollers(document);revealActiveSubcategory(document);}
document.body.addEventListener('htmx:historyRestore',function(){if(window.updateAddButtons)window.updateAddButtons();applyImgQuality(document);bindSubcategoryScrollers(document);revealActiveSubcategory(document);});window.hxClearCatSearch=function(inputId,clearBtnId){var inp=document.getElementById(inputId);var clr=clearBtnId?document.getElementById(clearBtnId):null;if(!inp)return;inp.value='';if(clr)clr.classList.remove('visible');htmx.trigger(inp,'input');inp.focus();};window.hxSyncSearch=function(pageInputId,navInputId){var page=document.getElementById(pageInputId);var nav=document.getElementById(navInputId);if(!page||!nav)return;if(page.value&&!nav.value)nav.value=page.value;nav.addEventListener('input',function(){page.value=nav.value;htmx.trigger(page,'input');});page.addEventListener('input',function(){nav.value=page.value;});};window.hxApplyImgQuality=applyImgQuality;})();